DROP TABLE IF EXISTS `lifeinvader_business_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `lifeinvader_business_sales` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `business_id` bigint(20) NOT NULL,
  `public_ref` varchar(16) NOT NULL,
  `seller_identifier` varchar(60) NOT NULL,
  `seller_name` varchar(120) NOT NULL,
  `total_cents` int(11) NOT NULL,
  `commission_cents` int(11) NOT NULL DEFAULT 0,
  `backdated` tinyint(1) NOT NULL DEFAULT 0,
  `note` varchar(300) DEFAULT NULL,
  `declared_at` datetime NOT NULL DEFAULT current_timestamp(),
  `client_firstname` varchar(32) DEFAULT NULL,
  `client_lastname` varchar(32) DEFAULT NULL,
  `client_dob` varchar(10) DEFAULT NULL,
  `client_phone` varchar(20) DEFAULT NULL,
  `vehicle_plate` varchar(12) DEFAULT NULL,
  `vehicle_record` enum('found','absent','unreadable') DEFAULT NULL,
  `vehicle_model` varchar(80) DEFAULT NULL,
  `vehicle_model_name` varchar(60) DEFAULT NULL,
  `vehicle_class` varchar(60) DEFAULT NULL,
  `vehicle_fleet_job` varchar(60) DEFAULT NULL,
  `vehicle_mods` text DEFAULT NULL,
  `client_ref` varchar(40) NOT NULL,
  `margin_cents` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_business_sales_ref` (`public_ref`),
  UNIQUE KEY `uq_business_sales_client_ref` (`business_id`,`client_ref`),
  KEY `idx_business_sales_biz_date` (`business_id`,`declared_at`),
  KEY `idx_business_sales_seller` (`business_id`,`seller_identifier`,`declared_at`),
  KEY `idx_business_sales_plate` (`business_id`,`vehicle_plate`)
) ENGINE=InnoDB AUTO_INCREMENT=2308 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

